package com.hardcraft.world;
import java.nio.file.*;import java.util.*;import org.bukkit.*;import org.bukkit.block.Block;import org.bukkit.event.block.BlockFromToEvent;import org.bukkit.event.entity.EntityExplodeEvent;import org.bukkit.plugin.java.JavaPlugin;
final class StagingProbe{
 private static final UUID OWNER=UUID.fromString("00000000-0000-0000-0000-000000000501"),TRUSTED=UUID.fromString("00000000-0000-0000-0000-000000000502");private final JavaPlugin plugin;private final ClaimService claims;
 StagingProbe(JavaPlugin p,ClaimService c){plugin=p;claims=c;}
 void run(){if(!Boolean.getBoolean("hardcraft.world.stagingProbe"))return;Bukkit.getScheduler().runTask(plugin,()->{World w=Bukkit.getWorlds().getFirst();Path marker=plugin.getDataFolder().toPath().resolve("staging-probe-prepared");if(Files.exists(marker)){verify(w,marker);return;}claims.create(OWNER,w.getUID().toString(),100,100,4,3).thenCompose(c->claims.trust(c.id(),TRUSTED,OWNER,true)).whenComplete((v,e)->Bukkit.getScheduler().runTask(plugin,()->{if(e!=null)fail(e);else try{Files.createDirectories(marker.getParent());Files.createFile(marker);plugin.getLogger().info("STAGING_PROBE PREPARED: claim and offline trust committed; restart required");Bukkit.shutdown();}catch(Exception x){fail(x);}}));});}
 private void verify(World w,Path marker){try{Claim c=claims.at(w.getUID().toString(),100,100).orElseThrow();if(!c.permits(OWNER)||!c.permits(TRUSTED))throw new IllegalStateException("claim/trust lost after restart");Block inside=w.getBlockAt(104,w.getMinHeight()+1,100),outside=w.getBlockAt(105,w.getMinHeight()+1,100);BlockFromToEvent fluid=new BlockFromToEvent(inside,outside);Bukkit.getPluginManager().callEvent(fluid);if(!fluid.isCancelled())throw new IllegalStateException("cross-boundary fluid allowed");List<Block> blocks=new ArrayList<>(List.of(inside,outside));EntityExplodeEvent explosion=new EntityExplodeEvent(null,inside.getLocation(),blocks,1f,ExplosionResult.KEEP);Bukkit.getPluginManager().callEvent(explosion);if(blocks.contains(inside)||!blocks.contains(outside))throw new IllegalStateException("explosion filtering failed");Files.delete(marker);plugin.getLogger().info("STAGING_PROBE PASS: startup/restart, claim persistence, offline trust, fluid boundary, explosion filtering");Bukkit.shutdown();}catch(Throwable e){fail(e);}}
 private void fail(Throwable e){plugin.getLogger().log(java.util.logging.Level.SEVERE,"STAGING_PROBE FAIL",e);Bukkit.shutdown();}
}